import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { likeCommentHandler } from "../handlers/likeCommentHandler";
import type { ApiError } from "../runtime/client";
import type { FeedPartition } from "../types/FeedPartition";
import type { PostCommentTargetEntityType } from "../types/PostCommentTargetEntityType";

type Data = Awaited<ReturnType<typeof likeCommentHandler>>;
type Vars = { postId: FeedPartition; commentId: PostCommentTargetEntityType; liked: boolean };

export function useLikeCommentHandler(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => likeCommentHandler(vars.postId, vars.commentId, vars.liked),
    ...options,
  });
}
